var n=`0711-maru-we-llham`;var t=`world-0711`;var a=`MR`;var r=`western-africa`;var o=4;var s=95;var l={en:`Maru We Llham`,ua:`Рис із м'ясом`};var u={en:`Maru We Llham is a Mauritania classic prepared with lamb, yellow onion, carrot, tomato. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Рис із м'ясом, страва кухні країни Мавританія зі складниками: ягнятина, жовта цибуля, морква, помідор. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var g=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 10 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 10 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:10,i:[[`lamb`,680,`g`],[`yellow-onion`,190,`g`],[`sunflower-oil`,45,`ml`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 55 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 55 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:55,i:[[`water`,750,`ml`],[`carrot`,260,`g`],[`tomato`,210,`g`],[`ground-cumin`,5,`g`]]},{en:`Spread the rice evenly into the flavorful liquid. Cook uncovered or partly covered for about 27 minutes until the liquid is absorbed; do not over-stir.`,ua:`Рівномірно розподіліть рис у ароматній рідині. Готуйте приблизно 27 хвилин до вбирання рідини, не перемішуючи надмірно.`,t:[`rice-washing`,`absorption-cooking`],m:27,i:[[`basmati-rice`,370,`g`],[`water`,550,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`parsley`,18,`g`]]}];var m={slug:n,id:t,country:`MR`,region:r,servings:4,minutes:95,title:l,text:u,steps:g};export{a as country,m as default,t as id,s as minutes,r as region,o as servings,n as slug,g as steps,u as text,l as title};